function roofQuantitiesDialog(){try{const q=roofBodyQuantities(p),v=n=>n.toFixed(2),names=['cover','deck','insulation','lining'],d=dialog('Dachmengen','<p>Geometrische Mengen der sichtbaren Flächen, Öffnungen und vertikalen Dachschichten. Ohne Verschnitt, Tragwerksbemessung oder baurechtliche Prüfung.</p><div class="archTable"><table><thead><tr><th>Dachkörper</th><th>Brutto m²</th><th>Öffnung m²</th><th>Netto m²</th><th>Traufe m</th></tr></thead><tbody>'+q.rows.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+v(r.gross)+'</td><td>'+v(r.opening)+'</td><td>'+v(r.net)+'</td><td>'+v(r.eaves)+'</td></tr>').join('')+'</tbody></table></div><h3>Schichtvolumen m³</h3><div class="archTable"><table><thead><tr><th>Dachkörper</th><th>Deckung</th><th>Unterdach</th><th>Dämmung</th><th>Innen</th></tr></thead><tbody>'+q.rows.map(r=>'<tr><td>'+esc(r.name)+'</td>'+names.map(k=>'<td>'+v(r.volumes[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>'+(q.limited?'Kantenmengen nicht berechnet: Dachkombination zu komplex.':'Firste / Grate: '+v(q.ridge)+' m · Kehlen: '+v(q.valley)+' m · Höhensprünge: '+v(q.steps)+' m')+'</p><button id="roofCSV">CSV exportieren</button><button id="roofQtyBack">Zurück</button>');d.querySelector('#roofCSV').onclick=()=>{const safe=s=>'"'+(/^[=+@-]/.test(s)?"'":"")+s.replaceAll('"','""')+'"';download('Dachmengen.csv',new Blob(['Dachkörper;Brutto m2;Öffnung m2;Netto m2;Traufe m;Deckung m3;Unterdach m3;Dämmung m3;Innen m3\n'+q.rows.map(r=>[safe(r.name),v(r.gross),v(r.opening),v(r.net),q.limited?'':v(r.eaves),...names.map(k=>v(r.volumes[k]))].join(';')).join('\n')+'\n\nFirste / Grate m;'+(q.limited?'':v(q.ridge))+'\nKehlen m;'+(q.limited?'':v(q.valley))],{type:'text/csv;charset=utf-8'}))};d.querySelector('#roofQtyBack').onclick=()=>{d.remove();roofBodiesDialog()}}catch(e){status(e.message)}}

function planSelect(label,id,opts,value){return '<label>'+esc(label)+'<select id="'+id+'">'+opts.map(([v,n])=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label>'}
function doorArcMarkup(o,a,b){if(['sliding','garage'].includes(o.style))return '';const count=o.style==='double'?2:1,w=b/count,side=o.swing==='out'?-1:1;let h='';for(let i=0;i<count;i++){const right=count===2?i===1:o.hinge==='right',x=a+(right?b:0),dx=right?-w:w;h+='<path pointer-events="none" d="M'+x+' 0v'+(side*w)+'a'+w+' '+w+' 0 0 '+((right!== (side<0))?1:0)+' '+dx+' '+(-side*w)+'" fill="none" stroke="#866d51"/>'}return h}
function polygonRoomDialog(){const d=dialog('Freier Raumumriss','<p>Koordinaten in Metern, eine Ecke pro Zeile: X; Y. Der letzte Punkt wird automatisch mit dem ersten verbunden. Exakt übereinstimmende vorhandene Wände werden wiederverwendet.</p><label>Eckpunkte<textarea id="roomPoints" rows="7">0;0\n6;0\n6;3\n4;3\n4;5\n0;5</textarea></label>'+field('Wandstärke m','polyThickness',.2)+'<div id="polyPreview" class="archPreview"></div><p id="polyInfo"></p><button id="polyApply" class="primary">Raum zeichnen</button>');const points=()=>d.querySelector('#roomPoints').value.trim().split(/\n+/).map(s=>{const a=s.trim().split(';').map(v=>Number(v.trim().replace(',','.')));if(a.length!==2||!a.every(Number.isFinite))throw Error('Je Zeile zwei Koordinaten mit Semikolon trennen');return {x:a[0],y:a[1]}}),refresh=()=>{try{const pts=points(),l=copy(L());polygonRoom(l,pts,num(d.querySelector('#polyThickness').value,.02,5));const minX=Math.min(...pts.map(q=>q.x)),minY=Math.min(...pts.map(q=>q.y)),s=Math.min(270/Math.max(.1,Math.max(...pts.map(q=>q.x))-minX),150/Math.max(.1,Math.max(...pts.map(q=>q.y))-minY));d.querySelector('#polyPreview').innerHTML='<svg viewBox="0 0 320 185" width="100%"><rect width="100%" height="100%" fill="#eff3ed"/><polygon points="'+pts.map(q=>(25+(q.x-minX)*s)+','+(18+(q.y-minY)*s)).join(' ')+'" fill="#d7ddcb" stroke="#43574d" stroke-width="3"/></svg>';d.querySelector('#polyInfo').textContent=pts.length+' Eckpunkte · gültiger Umriss'}catch(e){d.querySelector('#polyPreview').innerHTML='';d.querySelector('#polyInfo').textContent=e.message}};d.querySelectorAll('input,textarea').forEach(e=>e.oninput=refresh);d.querySelector('#polyApply').onclick=()=>{try{const pts=points(),th=num(d.querySelector('#polyThickness').value,.02,5);if(transact(()=>polygonRoom(L(),pts,th))){d.remove();mode='2d';walk=false;tool='select';render();fitPlan()}}catch(e){d.querySelector('#polyInfo').textContent=e.message}};refresh()}
function wallOperationDialog(k,l,w){const split=k==='wallSplit',d=dialog(split?'Wand teilen':k==='wallParallel'?'Parallele Wand':'Wand versetzen','<p>'+(split?'Abstand vom Wandanfang. Öffnungen dürfen nicht durchschnitten werden.':k==='wallParallel'?'Mittellinienabstand; negative Werte erzeugen die Kopie auf der Gegenseite. Keine Öffnungen werden kopiert.':'Versatz senkrecht zur Wand; verbundene Wandenden folgen.')+'</p>'+field(split?'Teilung bei m':'Versatz m','wallOffset',split?dist(w.a,w.b)/2:1)+'<button id="wallOpApply" class="primary">Übernehmen</button>');d.querySelector('#wallOpApply').onclick=()=>{try{const v=num(d.querySelector('#wallOffset').value,-100,100);if(transact(()=>{if(split)splitWall(l,w,v);else if(k==='wallParallel'){const n=parallelWall(l,w,v);selected={type:'wall',id:n.id}}else shiftWall(l,w,v)}))d.remove()}catch(e){status(e.message)}}}
function roomScheduleDialog(){const rows=p.levels.flatMap(l=>rooms(l).map(r=>({level:l.name,name:r.name,usage:roomUsages.find(q=>q[0]===r.usage)?.[1]||'Sonstiges',area:netFloor(p,l,r),perimeter:r.perimeter,height:r.clearHeight,volume:netFloor(p,l,r)*r.clearHeight}))),fmt=n=>n.toFixed(2),safe=s=>'"'+(/^[=+@-]/.test(s)?"'":"")+s.replaceAll('"','""')+'"',d=dialog('Raumliste','<p>Geometrische Bodenflächen abzüglich gültiger Durchbrüche. Volumen ist Bodenfläche × lichte Höhe, ohne Dachschrägen oder geschossübergreifende Lufträume.</p><div class="archTable"><table><thead><tr><th>Geschoss / Raum</th><th>Nutzung</th><th>m²</th><th>Umfang m</th><th>Höhe m</th><th>m³</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.level)+' / '+esc(r.name)+'</td><td>'+esc(r.usage)+'</td><td>'+fmt(r.area)+'</td><td>'+fmt(r.perimeter)+'</td><td>'+fmt(r.height)+'</td><td>'+fmt(r.volume)+'</td></tr>').join('')+'</tbody></table></div><button id="roomCSV">CSV exportieren</button><button id="openingSchedule">Tür- und Fensterliste</button>');d.querySelector('#openingSchedule').onclick=()=>{d.remove();openingScheduleDialog()};d.querySelector('#roomCSV').onclick=()=>download('Raumliste.csv',new Blob(['Geschoss;Raum;Nutzung;Fläche m2;Umfang m;Höhe m;Volumen m3\n'+rows.map(r=>[safe(r.level),safe(r.name),safe(r.usage),fmt(r.area),fmt(r.perimeter),fmt(r.height),fmt(r.volume)].join(';')).join('\n')],{type:'text/csv;charset=utf-8'}))}

