function costGeometry(){
 const q={floor:0,floorLabor:0,paint:0,wall:0,door:0,window:0,facade:0,roof:0,route:0,land:parcelCoverage(p)?.area||0},explicit=[],notes=[];
 for(const a of quantities(p)){q.floor+=a.floor;q.floorLabor+=a.floor;q.paint+=a.wallArea;q.wall+=a.wallVolume;q.door+=a.doors;q.window+=a.windows}
 for(const l of p.levels){for(const w of l.walls)q.facade+=facadeArea(w,wallCells(w));for(const r of l.routes||[]){const g=routeGeometry(r),a=routeSettings(r);if(a.price>0)explicit.push({name:l.name+' · '+(a.name||systems.find(s=>s.id===r.system).name),qty:g.length,unit:'m',rate:a.price});else q.route+=g.length}for(const o of l.objects){if(isKitchen(o)||isBathroom(o)){const a=isKitchen(o)?kitchenSettings(o):bathroomSettings(o);explicit.push({name:l.name+' · '+o.name,qty:1,rate:a.price})}}}
 // Polygon surface by Newell's vector; schematic, ignores separate automatic roof accessories.
 const area3=pts=>{let x=0,y=0,z=0;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];x+=(a[1]-b[1])*(a[2]+b[2]);y+=(a[2]-b[2])*(a[0]+b[0]);z+=(a[0]-b[0])*(a[1]+b[1])}return Math.hypot(x,y,z)/2};
 try{if(p.roofBodies?.length)q.roof=roofBodyQuantities(p).rows.reduce((s,r)=>s+r.net,0);else if(p.roofPatches?.length){q.roof=p.roofPatches.reduce((s,r)=>s+area3(r.points.map(a=>[a.x,a.z,a.y])),0);notes.push('Manuelle Dachflächen: geometrische Näherung.')}else{const roof=automaticRoof(p);if(roof)q.roof=roof.faces.reduce((s,f)=>s+area3(f.map(i=>roof.vertices[i])),0);else if(p.roof!=='none')notes.push('Dachfläche nicht berechenbar. Ergänze die Kosten manuell.')}}catch(e){notes.push('Dachfläche nicht berechenbar: '+e.message)}
 return {q,explicit,notes}
}
